(function(){if(!window.CET_DATA)window.CET_DATA={meta:{},exams:[]};window.CET_DATA.exams.push({"id":"2024-12-cet4-1","level":"CET4","year":2024,"month":12,"set":1,"title":"2024 �� 12 �� �� CET4 �� 1 ��","source":"��ѧӢ��CET4���� 2024 �� 12 �����⣨�� 1 �ף�","writing":{"prompt":"Directions: Suppose the business school of your university is conducting a survey to collect students�� opinions on the express\ndelivery service industry in China. You are to write a response about its recent development and its impact on people's lives.\nYou will have 30 minutes to write the essay. You should write at least 120 words but no more than 180 words.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 and 2 are based on the news report you have just heard.","questions":[{"n":1,"options":{"A":"She is making a special effort to be recognized.","B":"She has been living in Fayetteville for 25 years.","C":"She has been driving a school bus ever since 2009.","D":"She is the longest-serving bus driver in Fayetteville."},"answer":"D"},{"n":2,"options":{"A":"The importance of their service to the city.","C":"The new proclamation issued early this week.","B":"The number of riders they serve in the city.","D":"The significance of the event to take place March 18."},"answer":"A"},{"n":3,"options":{"A":"Budgeted $56.7 million for the coming school year.","C":"Proposed a spending increase by 5.99 percent.","B":"Requested to raise teachers�� salaries by 3 percent.","D":"Kept raising funds for at least 8 budget cycles."},"answer":"C"},{"n":4,"options":{"A":"Decrease in salaries for school administrators.","C":"Firing of less qualified faculty members.","B":"Reduction in federal and state funding.","D":"Closing down of some less competitive schools."},"answer":"B"},{"n":5,"options":{"A":"They often take place in the Scottish Highlands.","C":"Their damage can be as serious as that of bombs.","B":"They usually happen in the middle of the night.","D":"Their loud claps can be confused with explosions."},"answer":"D"},{"n":6,"options":{"A":"They sent out a message to calm them down.","C":"They told them the military exercise was over.","B":"They promised to stop the construction work.","D":"They set off to inspect the site of the plane crash."},"answer":"A"},{"n":7,"options":{"A":"Keep warm.","C":"Avoid driving.","B":"Take caution.","D":"Use rail service."},"answer":"B"}]},{"intro":"Questions 8 to 11 are based on the conversation you have just heard.","questions":[{"n":8,"options":{"A":"Why the man is so anxious to buy a new phone.","C":"How the man got into the habit of being wasteful.","B":"How the man could possibly afford a new phone.","D":"Why the man is so fond of using his credit card."},"answer":"B"},{"n":9,"options":{"A":"It is not in fashion any more.","C":"It is not as fancy as his colleagues��.","B":"It goes out of order frequently.","D":"It lacks functions office work requires."},"answer":"C"},{"n":10,"options":{"A":"It enables him to buy a new phone at a more favorable price.","B":"It is a special offer to recent college graduates working in offices.","C":"It is available to office workers who have a good enough credit score.","D":"It allows him to borrow money without paying interest for six months."},"answer":"D"},{"n":11,"options":{"A":"She borrowed money to pay her debt.","B":"She developed a habit of overspending.","C":"She enjoys buying a lot of fancy things.","D":"She regrets ignoring the woman��s advice."},"answer":"B"},{"n":12,"options":{"A":"Blog writing and natural resources saving.","B":"Joint efforts to improve the local community.","C":"Audience participation in The Morning Show.","D":"Home ownership and environmental protection."},"answer":"D"},{"n":13,"options":{"A":"Not a realistic size for families.","C":"Only fit for families of four or less.","B":"Not welcomed by most Americans.","D":"Only suitable for renting to the poor."},"answer":"A"},{"n":14,"options":{"A":"It should be changed.","C":"It will come true sooner or later.","B":"It isn��t easy to realize.","D":"It doesn��t appeal to average families."},"answer":"A"},{"n":15,"options":{"A":"They help to lower housing prices.","C":"They are a good choice for many people.","B":"They help to save up for larger houses.","D":"They are vital to reducing waste worldwide."},"answer":"C"}]},{"intro":"Questions 16 to 18 are based on the passage you have just heard.","questions":[{"n":16,"options":{"A":"Play outdoors and enjoy themselves.","C":"Take care of their well-being.","B":"Beat challenges and take risks.","D":"Grow up strong and healthy."},"answer":"B"},{"n":17,"options":{"A":"Enable them to develop their motor skills.","C":"Reduce their stress and depression.","B":"Help them to conceal their frustration.","D":"Prevent them from feeling lonely."},"answer":"C"},{"n":18,"options":{"A":"It begins early.","C":"It calls for lifelong efforts.","B":"It proves demanding.","D":"It lies in nature experiences."},"answer":"A"},{"n":19,"options":{"A":"When companies share their information online.","C":"When companies embrace greater diversity","B":"When their job search criteria are met fully.","D":"When they find job postings visually attractive."},"answer":"C"},{"n":20,"options":{"A":"Emails in the normal format.","C":"All companies in the same sector","B":"Major companies in one location.","D":"Various aspects of a company��s workforce."},"answer":"A"},{"n":21,"options":{"A":"Job security","C":"Minimum base salary.","B":"Potential pay raises.","D":"Information about diversity."},"answer":"D"},{"n":22,"options":{"A":"Positive.","C":"Important.","B":"Original.","D":"Surprising."},"answer":"C"},{"n":23,"options":{"A":"Dogs match their behavior with kids as much as with adults.","B":"Kids and adults alike find in dogs a source of attachment.","C":"Kids�� attitude to dogs is influenced by adults.","D":"Dogs can help kids in many ways."},"answer":"D"},{"n":24,"options":{"A":"Dogs pay much attention to the kids they live with.","B":"Dogs view both adults and kids as social companions.","C":"Kids differ from adults in their behavior towards dogs.","D":"Kids need to be aware of the risks in playing with dogs."},"answer":"A"},{"n":25,"options":{"A":"Understanding dogs.","C":"Taking care of dogs.","B":"Training dogs.","D":"Associating with dogs."},"answer":"B"}]}]},"cloze":{"passage":"Directions: In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list\nof choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each\nchoice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single\nline through the centre. You may not use any of the words in the bank more than once.\n\nWhen Toni Morrison died in 2019, the world lost one of its most influential authors. But Morrison was not an early success.\nHer first novel was not published until she was 39, and her last appeared when she was 84. And Morrison was not ___26___\nin this regard. Numerous writers produce masterpieces well into their 70s and beyond. Such ___27___ accomplishments\nhighlight an important point. Our capacity to speak, write and learn new vocabulary does not seem to ___28___ with age. Our\neyesight may dim and our recall may weaken, but by comparison, our ability to produce and to ___29___ language is well\npreserved into older adulthood.\nIndeed, the latest research that has emerged on language and aging shows that language mastery is a ___30___ that we begin\nas infants and continue on for the rest of our lives. Some aspects of our language abilities, such as our knowledge of word\nmeanings, ___31___ improve during middle and late adulthood. One study, for example, found that adults over sixty had an\naverage vocabulary size of over 21,000 words. The researchers also studied a ___32___ of college students and found that\ntheir average vocabulary contained ___33___ 16,000 words. In another study, older adults, with an average age of 75,\n___34___ better than participants in their youth or middle years on tasks that required them to determine the meaning of\nwords. Thus, language seems to be a skill that, contrary to what many might ___35___, does not weaken with age.","bank":[["A","actually"],["I","literary"],["B","approximately"],["J","performed"],["C","assume"],["K","rarely"],["D","component"],["L","sample"],["E","comprehend"],["M","undermined"],["F","deteriorate"],["N","unique"],["G","equivalent"],["O","unit"],["H","journey"]],"answers":{"26":"N","27":"I","28":"F","29":"E","30":"H","31":"A","32":"L","33":"B","34":"J","35":"C"}},"matching":{"statements":[{"n":36,"text":"According to a management expert, work-life balance is not as simple as giving equal amounts of time to work and\npersonal life.","answer":"B"},{"n":37,"text":"Research found that those who are given greater flexibility at work are less stressed and more likely to stay in their jobs.","answer":"J"},{"n":38,"text":"Workers who rejected working long hours tended to make regular adjustments in order to achieve work-life balance.","answer":"E"},{"n":39,"text":"Talking about work-life balance is said to be a privilege reserved for the better-off, not for those who barely make a living.","answer":"L"},{"n":40,"text":"Knowing one��s emotional state is of utmost importance in deciding what changes to make for a better work-life balance.","answer":"G"},{"n":41,"text":"More female professionals reported being reluctant to work overtime than their male counterparts.","answer":"D"},{"n":42,"text":"Without organisational support, any personal effort to maintain work-life balance will be unsuccessful.","answer":"K"},{"n":43,"text":"The question of how to achieve work-life balance has long been the main subject of discussion among workers.","answer":"A"},{"n":44,"text":"You may not actually experience emotional wellbeing at home if you remain occupied with what happened at work.","answer":"H"},{"n":45,"text":"Some researchers suggest that work-life balance is not a goal to achieve, but a process for life to be adjusted promptly.","answer":"C"}],"note":"�����𰸼��ѽ��룻��������������롣"},"reading":[{"title":"Passage One","passage":"The weakening of the human connection to nature might be good for economic growth but is bad for people. A tipping\npoint was reached in 2020 when human-made materials �� such as steel, concrete and plastic �� were found to weigh more\nthan all life on Earth. Continuing to grow concrete forests rather than real ones is shortsighted. Simply being in the nearest\nwood has such health benefits that the Woodland Trust successfully lobbied for it to be prescribed by doctors.\n      Yet slipping from popular culture is the wonder and beauty of the natural world. For every three nature-related words in\nhit songs of the 1950s, researchers found, there was only slightly more than one 50 years later. It is not a moment too soon\nthat teenagers will be able to take a natural history test given that for decades children have been able to name more video\ngame characters than wildlife species.\n      Part of remedying this social disease would be for parliament to pass a ��right to grow�� law, allowing anyone to turn\nunderused public spaces into vegetable and fruit gardens. The idea is for people to get back in touch with the soil �� while\nproducing food sustainably.\nVegetable planting has a respectable tradition. In April 1649, locals responded to high prices and food shortages by cultivating\nvegetables on common land in Southern England. The practice of throwing seed bombs to turn vacant plots of land green took\noff in 1970s New York, and has been revived (ʹ����) by green-thumbed (��԰�ղ��ܵ�) social media influencers who defy\nlocal US regulations in a war on ugly spots in cities.\n      Apart from the urgent task of providing more healthy nutrients to those who increasingly can��t afford them. Publicly\naccessible fruit and vegetable gardens connect what we eat to where it comes from��the means of production, if you will.\nThey can make unlovely spaces lovely, and marry use and beauty as well as help promote a sense of community. Plants are\nalso, of course, our first defense against species loss and climate change. Such planting is a small step for humanity �� in the\nright direction.","questions":[{"n":46,"stem":"What does the author want to emphasize in the first paragraph?","options":{"A":"The year 2020 was a big turning point in human history.","B":"Economic growth benefits people little in the long run.","C":"It is unwise to weaken the human connection to nature.","D":"It is harmful to mankind to use human-made materials."},"answer":"C"},{"n":47,"stem":"What did researchers find about popular culture?","options":{"A":"It is increasingly detached from the natural world.","B":"It is filled with all kinds of video game characters.","C":"It is especially appealing to the taste of teenagers.","D":"It is still impacted by the hit songs of the 1950s."},"answer":"A"},{"n":48,"stem":"What does the author propose people do?","options":{"A":"Take measures to ensure sustainable food development","B":"Reconnect with nature through the right to grow.","C":"Stand by the parliament in fighting social diseases.","D":"Cover public spaces with fruit trees and vegetable plants."},"answer":"B"},{"n":49,"stem":"What do we learn from the passage about vegetable planting?","options":{"A":"It all started in 1649 in Southern England.","B":"It is protected by US government regulations.","C":"It has long been used to increase food supply and improve urban landscape.","D":"It has been popularized worldwide with the increasing influence of social media."},"answer":"C"},{"n":50,"stem":"What can publicly accessible fruit and vegetable gardens do apart from their practical functions?","options":{"A":"Raise people��s environmental awareness.","C":"Act as the first defense against natural disasters.","B":"Add to the great variety of plant species.","D":"Enhance people��s community spirit."},"answer":"D"}]},{"title":"Passage Two","passage":"Engineering in the U.S. has long been a male-dominated profession. Fifty years ago, it looked like that might change.\n     In 1970, the percentage of women majoring in engineering was less than 1%. In 1979, that number was 9%. Many hoped\nwomen would continue to enter the field at the same rate. But that��s not what happened. Today, only 21% of engineering\nmajors are women, a number largely unchanged since 2000.\n     I am a historian who, along with my colleagues, surveyed 251 women engineers who graduated from college in the\n1970s. These pioneers reflected on the challenges they faced �� and had advice for women entering the field today.\n     One survey taker explained, ��The greatest challenge for me was continuing to believe in myself, when all the messages\nI was getting were that I would never be taken seriously or promoted or given raises at the same rate as men, who were clearly\nless qualified and not as smart as I was.��\n     A chemical engineer who worked in manufacturing agreed, ��You have to prove yourself just because you are female.\nAnd you have to work twice as hard!��\n     A civil engineer said, ��We are ��women engineers.�� People don��t refer to a man as a ��man engineer�� �� he��s an engineer.\nWe are constantly reminded that we don��t truly belong.�� Another civil engineer stated, ��On many levels, you��re never quite\none of the groups.��\n     Women also talked about family caregiving responsibilities. A retired vice president from a major chemical company\nstated, ��Young women engineers are on an equal footing until they have children, then they struggle to balance work and\nfamily��and compete with men who don��t have the same household responsibilities.��\n     But over the years, things have changed a lot. Young women engineers are more accepted mostly because there are just\nmore of them. Many women engineers hailed the benefits of their chosen career. A program manager in manufacturing stated\nthat engineering is the best degree. A mechanical engineer said, ��It will give you the flexibility to do almost anything. It is\nalso satisfying to see the effects of what you have done.��","questions":[{"n":51,"stem":"What does the passage say about the engineering profession in the United States?","options":{"A":"It has seen a change in attitude towards women engineers since 1979.","B":"It witnessed a significant increase in women engineers in the 1970s.","C":"It has experienced the gradual weakening of male dominance.","D":"It boasted the largest number of engineering majors in 2000."},"answer":"B"},{"n":52,"stem":"What does one survey taker say was her greatest challenge?","options":{"A":"Not to feel superior to less qualified male engineers.","B":"Not to take seriously all the messages she was getting.","C":"Not to think highly of her qualifications when promoted or given a pay raise.","D":"Not to lose self-confidence though constantly discouraged or unfairly treated."},"answer":"D"},{"n":53,"stem":"How do women engineers frequently feel according to the two civil engineers?","options":{"A":"Disqualified on many levels.","C":"Overworked by their organizations.","B":"Excluded from the group.","D":"Looked down upon by male colleagues."},"answer":"B"},{"n":54,"stem":"What probably makes young women engineers more accepted nowadays?","options":{"A":"Their success in gaining an equal footing.","C":"The change in their responsibilities.","B":"Their ability to balance work and family.","D":"The increase in their number."},"answer":"D"},{"n":55,"stem":"What can we conclude about many female engineers from the statement of a mechanical engineer?","options":{"A":"They take great pride in their chosen career.","B":"They have reaped the benefits of being flexible.","C":"They enjoy doing engineering to the best degree.","D":"They have proved capable of doing almost anything."},"answer":"A"}]}],"translation":{"prompt":"Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your\nanswer on Answer Sheet 2.\n\n�й�����ʮ�����ӻ���������������,�й��ڼ��ٿ�����ˮ��������Ⱦ��ȡ����������Ч��Ϊ�˲��ϸ������ǵ�����\n����,�й���ȡ��һϵ����Ч��ʩ,����������չ�����Դ,���ƹ�����ͨ,�ƹ㹲�����,ʵʩ�������ࡣͨ����Щ\n��ʩ,�й��ĳ��к�ũ�����������������������й�������������ʺ���,Ϊȫ�򻷾�������������Ҫ���ס�","guide":[]}});window.CET_DATA.exams.push({"id":"2024-12-cet4-2","level":"CET4","year":2024,"month":12,"set":2,"title":"2024 �� 12 �� �� CET4 �� 2 ��","source":"��ѧӢ��CET4���� 2024 �� 12 �����⣨�� 2 �ף�","writing":{"prompt":"Directions: Suppose the university newspaper is inviting submissions from the students for its coming edition on how to enrich\nstudents�� knowledge of traditional Chinese culture. You are now to write an essay for submission. You will have 30 minutes to\nwrite the essay. You should write at least 120 words but no more than 180 words.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 and 2 are based on the news report you have just heard.","questions":[{"n":1,"options":{"A":"They will see a 27% higher price to buy natural gas.","B":"They will have insufficient heating oil to keep warm.","C":"They will have a costly bill to pay to heat their homes.","D":"They will experience the coldest winter in four decades."},"answer":"C"},{"n":2,"options":{"A":"Provided additional funding to Low Income Home Energy Assistance Program.","B":"Assured U.S. citizens of an increase in energy supplies by the end of this year.","C":"Predicted a 10% jump in heating bills for most U.S. households this winter.","D":"Decided on this year��s energy assistance package of $8 billion in total."},"answer":"A"},{"n":3,"options":{"A":"They care less about their diet now than before.","B":"They may lack adequate knowledge of healthy food.","C":"They may hold too optimistic a view about their diet.","D":"They pay insufficient attention to their choice of food."},"answer":"C"},{"n":4,"options":{"A":"Those who finished 24-hour food questionnaires.","C":"Those who cared about food quality.","B":"Those who fully understood the rating scale.","D":"Those who rated their diet as poor."},"answer":"D"},{"n":5,"options":{"A":"They experienced a heartbreaking moment.","C":"They heard a noise from the bottom of a well.","B":"They gathered together to rescue an elephant.","D":"They found an elephant wandering around a well."},"answer":"B"},{"n":6,"options":{"A":"To borrow their crane.","C":"To report the strange noise.","B":"To ask them for help.","D":"To get food for the elephant."},"answer":"B"},{"n":7,"options":{"A":"The elephant was able to return to the jungle.","B":"The army officers were examined for injuries.","C":"The army officers were rewarded for their rescue efforts.","D":"The elephant was given medical treatment for many days."},"answer":"A"}]},{"intro":"Questions 8 to 11 are based on the conversation you have just heard.","questions":[{"n":8,"options":{"A":"He found it had caused him much inconvenience.","B":"It led him to spend more money than necessary.","C":"It was much less secure than paying with cash.","D":"He wanted to be less dependent on his phone."},"answer":"B"},{"n":9,"options":{"A":"Living beyond her means.","C":"Fashion addiction.","B":"Lack of budgeting strategies.","D":"Impulse purchasing."},"answer":"D"},{"n":10,"options":{"A":"Eat healthier food with less money.","C":"Avoid getting addicted to junk food.","B":"Order food like burgers and chips.","D":"Pay either in cash or with his phone."},"answer":"A"},{"n":11,"options":{"A":"Making a shopping list.","C":"Withdrawing cash only once a month.","B":"Sticking to his budget.","D":"Thinking twice before buying something."},"answer":"B"},{"n":12,"options":{"A":"He does not enjoy any ball games.","C":"He has breathing problems.","B":"He has to prepare for the future.","D":"He is not up to anything challenging."},"answer":"C"},{"n":13,"options":{"A":"Soccer","C":"Volleyball.","B":"Badminton.","D":"Basketball."},"answer":"D"},{"n":14,"options":{"A":"The possibilities of joining the school sports team.","B":"The opportunities of winning some championships.","C":"The chances of getting an athletic scholarship later on.","D":"The odds of becoming a professional sportsman someday."},"answer":"C"},{"n":15,"options":{"A":"It differs entirely from indoor volleyball.","C":"It is less popular than indoor sports in the country.","B":"It appeals to both schoolgirls and schoolboys.","D":"It is completely different from other outdoor games."},"answer":"A"}]},{"intro":"Questions 16 to 18 are based on the passage you have just heard.","questions":[{"n":16,"options":{"A":"It usually requires years of preparations.","B":"It does a lot of harm to the environment","C":"It often burns over three hundred tonnes of refined fuel.","D":"It proves to be the most complicated stage of space missions."},"answer":"B"},{"n":17,"options":{"A":"They are burnt up in outer space.","C":"They are reused up to 100 times.","B":"They are guided back to Earth.","D":"They are treated as expendable."},"answer":"D"},{"n":18,"options":{"A":"New technologies for bringing back space vehicles for recycling.","B":"The technology for meeting the needs of commercial space travel.","C":"Many of the technologies to limit the impact of space travel on Earth.","D":"The technology for effectively protecting ozone from being destroyed."},"answer":"C"},{"n":19,"options":{"A":"It can help unskilled readers feel more secure.","B":"It can encourage reluctant readers to read aloud.","C":"It can strengthen children��s confidence in others.","D":"It can boost children��s interest in communication."},"answer":"B"},{"n":20,"options":{"A":"By motivating children to find out about their favourite pets.","B":"By taking children to the library to borrow books on animals.","C":"By allowing children to surf the internet about pets by themselves.","D":"By showing children how to acquire knowledge about healthy pets."},"answer":"A"},{"n":21,"options":{"A":"By learning that raising pets can do much good.","C":"By hearing about their peers�� passion for pets.","B":"By watching how healthy pets are brought up.","D":"By visiting friends who have household pets."},"answer":"D"},{"n":22,"options":{"A":"Send would-be students a packet of information.","B":"Update regularly all information on their websites.","C":"Inform prospective students of their yearly enrollment.","D":"Answer questions raised by applicants and their parents."},"answer":"A"},{"n":23,"options":{"A":"Oversee private institutions directly.","C":"Supervise all schools consistently.","B":"Follow other states�� example.","D":"Regulate public institutions by law."},"answer":"D"},{"n":24,"options":{"A":"They are resourceful.","B":"They are competitive.","C":"They provide the best opportunity to realize one��s dream.","D":"They appeal most to students from other states in the U.S."},"answer":"B"},{"n":25,"options":{"A":"Some students waste much time surfing the net.","C":"Students have to search for the information.","B":"Students may need to visit too many websites.","D":"Some students may lack adequate access."},"answer":"C"}]}]},"cloze":{"passage":"Directions: In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list\nof choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each\nchoice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single\nline through the centre. You may not use any of the words in the bank more than once.\n\nScientists have known that depriving adult mice of vision can increase the sensitivity of individual neurons (��Ԫ) in the\npart of the brain devoted to hearing. New research from biologists at the University of Maryland ___26___ that sight\ndeprivation also changes the way brain cells ___27___ with one another, shifting the mice��s sensitivity to different frequencies.\n��This study ___28___ what we are learning about how manipulating vision can have a ___29___ effect on the ability of an\nanimal to hear long after the window for auditory (������) learning was thought to have ___30___ said Patrick Kanold,\nsenior author of the study.\nIt was once thought that the sensory regions of the brain were not ___31___ after a critical period in childhood. This is why\nchildren learn languages much more ___32___ than adults. Kanold��s earlier research disproved this idea by showing that\ndepriving adult mice of vision for a short period increased the sensitivity of individual neurons in the auditory cortex (Ƥ��),\nwhich is devoted to hearing.\nYoung brains wire themselves according to the sounds they hear frequently, assigning areas of the auditory cortex to ___33___\nfrequencies based on what they are used to hearing. The researchers found that in adult mice, a week in the dark also changed\nthe ___34___ of space to different frequencies.\n��We don��t know why we are seeing these patterns,�� Kanold said. ��We ___35___ that it may have to do with what the mice\nare paying attention to while they are in the dark.��","bank":[["A","adaptable"],["I","readily"],["B","closed"],["J","registered"],["C","distribution"],["K","reinforces"],["D","interact"],["L","revealed"],["E","narration"],["M","significant"],["F","neutral"],["N","specific"],["G","permanently"],["O","speculate"],["H","prescribes"]],"answers":{"26":"L","27":"D","28":"K","29":"M","30":"B","31":"A","32":"I","33":"N","34":"C","35":"O"}},"matching":{"statements":[{"n":36,"text":"Judging from the slowing rate of sales growth, there is still hope to combat bottled water.","answer":"E"},{"n":37,"text":"Bottled water manufacturers base their arguments against bans of plastic bottles on health concerns rather than on profits. ��","answer":"H"},{"n":38,"text":"Sales of bottled water in Britain hit a record high last year even though people are increasingly aware that plastics are\nenvironmentally unfriendly.","answer":"B"},{"n":39,"text":"It often happens that people can lack reason when faced with skillful marketing.","answer":"L"},{"n":40,"text":"One city on the west coast of America has banned single-use bottles from its property and events.","answer":"G"},{"n":41,"text":"Manufacturing and shipping of plastic water bottles consume a tremendous amount of fossil fuels.","answer":"C"},{"n":42,"text":"One large beverage company has adapted its operations when confronted with challenges from health and environmental\nadvocates.","answer":"K"},{"n":43,"text":"Bottled water is considerably more expensive than tap water.","answer":"A"},{"n":44,"text":"Fountains could be seen in cities before bottled water became popular","answer":"I"},{"n":45,"text":"More people have taken to bottled water because of their health awareness.","answer":"F"}],"note":"�����𰸼��ѽ��룻��������������롣"},"reading":[{"title":"Passage One","passage":"As a university student I've come to realise just how little I know about money. I��ve come to the brutal realisation that\nAustralia��s youth are being done a great disservice by not receiving any consistent financial education.\n      Diving headfirst into the crash course of starting university, I��ve quickly tried to get myself up to speed with the financial\nterms of the modern era to help manage my personal finances.\n      I��ve read some financial education books, done some online learning, and have spoken to my nearest and dearest for\ntheir pearls of financial wisdom.\n      There are undoubtedly hundreds of great resources out there for those wishing to improve their financial literacy, but\nwhile I was researching, I still kept wishing that I didn��t have to play catch-up with the money world. I felt that L was sailing\nthe financial seas with no skills and no life jacket!\n      However, after talking to my friends who felt the same, I quickly realised that it wasn��t my ignorance but the lack of\nfinancial education in our schooling system that is leaving high schoolers seriously behind in the modern world of money.\n      Let��s compare a theoretical financial education subject to the standard compulsory English class. On average, English\nmay not be the most popular subject, but it��s consistently on the schedule throughout high school, with all students graduating\nfluent in English.\n      A financial education subject should do just the same. It shouldn��t be just a one-day event but a course integrated\nthroughout the whole of high school that would allow students to gradually expand their financial literacy, and would prevent\nthe need for a ��catch up�� phase once we��re out on our own after graduation.\n      In the same way that learning a language or new skills takes time, building financial skills requires practice and years to\ngradually accumulate bits and pieces of knowledge.\n      Giving young people the opportunity to become familiar with the world of money would provide them with a great\nadvantage to enter adulthood with confidence and security so that they are able to manage their own money and look after\nthemselves.","questions":[{"n":46,"stem":"What has the author come to realise since entering university?","options":{"A":"He needs a crash course on financial terms.","B":"He is very much lacking in financial literacy.","C":"It requires consistent education to be financially independent.","D":"It is unrealistic to give all Australian youth a financial education."},"answer":"B"},{"n":47,"stem":"How did the author feel in today��s money world?","options":{"A":"Badly equipped to survive.","C":"Barely capable of moving ahead.","B":"Ignorant of financial literature.","D":"Overwhelmed by the resources online."},"answer":"A"},{"n":48,"stem":"What did the author realise after talking to his friends?","options":{"A":"They were as keen as he was on financial matters.","B":"The schooling system was to blame for his trouble.","C":"High schoolers knew nothing about the modern financial world.","D":"Financial courses were as unpopular as compulsory English classes."},"answer":"B"},{"n":49,"stem":"What is the author��s idea of a financial education course?","options":{"A":"It should foresee students�� needs after graduation.","B":"It should provide students with some basic knowledge.","C":"It should be taught the same way as English is taught.","D":"It should be integrated into high school education."},"answer":"D"},{"n":50,"stem":"What would financial literacy do to young people?","options":{"A":"Allow them to enter adulthood with financial security.","B":"Enable them to look after themselves without worrying about money.","C":"Render them confident and secure in terms of money management.","D":"Help them become familiar with the world of money."},"answer":"C"}]},{"title":"Passage Two","passage":"Chocolates save us from many things, especially emotional distress. They comfort us in times of trouble, calming down\na racing heart by channeling happy calories inside us. We all have faith in chocolates to delight us in an instant!\n     Recently, chocolate lovers were heartbroken as scientists claimed that they can become extinct by 2050! But hey, we\nhave some happy news for you. Scientists can still help save chocolates from dying out! If you are not aware as to why\nscientists made the statement about the death of this wonderful thing, let us tell you the facts. Chocolate trees, whose seeds\nare used to make chocolate, grow in the tropical plant world and require very specific weather conditions to prosper.\n     Now, fifty percent of the world��s cocoa (�ɿ�) beans come from two countries in West Africa: Cote d��Ivoire and Ghana.\nScientists believe that both of these countries will experience a 3.8F temperature increase by 2050 due to global warming,\nendangering the cacao (�ɿ���) farms in the rainforests. These farms will then have to be shifted to cooler mountainous areas,\nwhich are the natural habitat of wildlife. This will lead to some tough decisions: whether to grow chocolate or save wildlife.\n     Unfortunately, the crisis of global warming has already had a serious negative impact on cacao farms�� yields, leading to\nthe prices of chocolates skyrocketing.\n     Scientists, however, are trying to find a long-term and eco-friendly solution to this problem! They are trying to modify\nthe species with a gene-editing technology, which will transform the seedlings into a species that survives even in a drier and\nwarmer climate.\n     According to a report by The Business Insider, in the University of California��s new bio-sciences building, tiny green\ncacao seedlings are lined up in refrigerated greenhouses for a new experiment by using a technology called CRISPR. By\nmanipulating the DNA of plants, this technology is already being used across the world to make plants tougher and cheaper.\nSimilarly, in this unconventional experiment, scientists will make tiny, precise changes to the DNA of the seedlings to make\nthe cocoa crops survive in warmer and drier climates.","questions":[{"n":51,"stem":"What do people believe chocolates can do?","options":{"A":"Cheer them up instantly.","C":"Conceal emotional distress.","B":"Create happy calories.","D":"Relieve them of heart trouble."},"answer":"A"},{"n":52,"stem":"What was scientists�� recent assertion about chocolates?","options":{"A":"They could become a rare treat in the near future.","B":"They could calm people down a bit in times of crisis.","C":"They could prevent people from getting heartbroken.","D":"They could become unavailable in less than 30 years."},"answer":"D"},{"n":53,"stem":"What would happen if the cacao farms were shifted to cooler mountainous areas?","options":{"A":"The natural habitat of wildlife there would be ruined.","B":"The cacao farmers would have a tough time to adapt.","C":"The rainforests would be shrinking dramatically.","D":"The quality of cocoa beans would suffer greatly."},"answer":"A"},{"n":54,"stem":"What do we learn about the cacao farms in the crisis of global warming?","options":{"A":"They try to seek help from gene-editing scientists.","B":"They decide to move to cooler mountainous areas.","C":"They have suffered a lot due to a decrease in produce.","D":"They have benefited by raising prices of cocoa beans."},"answer":"C"},{"n":55,"stem":"What are scientists trying to do in the University of California��s new bio-sciences building?","options":{"A":"Build rows of refrigerated greenhouses for research on cacao seedlings.","B":"Gene-edit cacao seedlings for them to withstand a drier, warmer climate.","C":"Produce chocolates with the latest gene-editing technology.","D":"Transplant the genes of tougher plants to cacao seedlings."},"answer":"B"}]}],"translation":{"prompt":"Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your\nanswer on Answer Sheet 2.\n\n������,�й�����Դ������ҵ��չѸ�١�Ŀǰ,�й�����Դ����������Ѹߴ��ǧ����,ռȫ���г��ݶ�� 60%,����\n�����ϴ����¸ߡ��й�����ͨ���Ӵ��ʽ�Ͷ�����������,��������Դ������ҵ���м�������,������߲�Ʒ���г�\n�ϵľ��������й�����Դ������ҵ�ķ�չ���������ƶ��˹��ھ��÷�չ,ҲΪȫ������Դ���úͻ������������˻�\n�����ס�","guide":[]}});window.CET_DATA.exams.push({"id":"2024-12-cet4-3","level":"CET4","year":2024,"month":12,"set":3,"title":"2024 �� 12 �� �� CET4 �� 3 ��","source":"��ѧӢ��CET4���� 2024 �� 12 �����⣨�� 3 �ף�","writing":{"prompt":"Directions: Suppose the university newspaper is inviting submissions from the students for its coming edition on how the\nstudents can contribute to a green campus. You are now to write an essay for submission. You will have 30 minutes to write\nthe essay. You should write at least 120 words but no more than 180 words.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 听力音频待接入；题干在音频中，卷面只给选项。","groups":[]},"cloze":{"passage":"Directions: In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list\nof choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each\nchoice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single\nline through the centre. You may not use any of the words in the bank more than once.\n\nSuper realistic masks are made from flexible materials such as silicone and are designed to imitate real human face �� down\nto every last detail.\nIn a study by the Universities of York and Kyoto, researchers asked participants to look at pairs of photographs and decide\nwhich showed a ___26___ face and which showed a person wearing a mask.\nSurprisingly, participants made the wrong call in one-in-five cases.\nThe 20% error rate ___27___ in the study likely underestimates the extent to which people would struggle to tell an ___28___\nface from the real thing outside of the lab.\nThe researchers collected data from participants from both the UK and Japan to ___29___ any differences according to race.\nWhen trial participants were asked to choose between photographs of faces of a different race from theirs, response times\nwere slower and selections were 5% less ___30___.\nThere are now dozens of criminal cases in which offenders have ___31___ themselves off as people of a different age, race\nor gender, sending police investigations down the wrong path.\nIn one recent case, an international gang used an ___32___ realistic mask to pose as a French minister, ___33___ business\nexecutives out of millions of pounds.\nDr. Jet Sanders, who worked on the study while a PhD student at the University of York, said: ��Failure to detect synthetic\nfaces may have important implications for security and crime prevention as super realistic masks may ___34___ the key\ncharacteristics of a person��s appearance to be ___35___ identified.��","bank":[["A","accurate"],["I","incorrectly"],["B","allow"],["J","normal"],["C","artificial"],["K","observed"],["D","cheating"],["L","passed"],["E","deserted"],["M","reminding"],["F","establish"],["N","reparable"],["G","extremely"],["O","resolve"],["H","immediately"]],"answers":{"26":"J","27":"K","28":"C","29":"F","30":"A","31":"L","32":"G","33":"D","34":"B","35":"I"}},"matching":{"statements":[{"n":36,"text":"Acquisition of new knowledge may not guarantee the progress that you aim to make.","answer":"C"},{"n":37,"text":"Your current situation in life is built on the beliefs and habits you have been practicing daily.","answer":"J"},{"n":38,"text":"Knowing the best way to learn a foreign language will not enable you to speak it without actual practice.","answer":"F"},{"n":39,"text":"People may find it demanding to create a goal which will take a long time to achieve.","answer":"A"},{"n":40,"text":"Learning and practicing seem to be very much alike, but the two processes can lead to quite different outcomes.","answer":"E"},{"n":41,"text":"Absorbing new information is helpful in making better decisions prior to action.","answer":"K"},{"n":42,"text":"Sometimes we may feel like we are making progress by doing some research or making preparations, but actually we are\nstaying at the starting point.","answer":"G"},{"n":43,"text":"We are inclined to think that a lack of knowledge prevents us from advancing to a better future.","answer":"B"},{"n":44,"text":"Learning can benefit you by itself but only practice can turn what you learn into meaningful contributions.","answer":"I"},{"n":45,"text":"Practice involves repeating a process intentionally to attain a particular objective.","answer":"D"}],"note":"�����𰸼��ѽ��룻��������������롣"},"reading":[{"title":"Passage One","passage":"Research in human-vehicle interaction has shown even systems designed to automate driving are far from being error-\nproof. Recent evidence points to drivers�� limited understanding of what these systems can and cannot do as a contributing\nfactor to system misuse. A recent study tackles the issue of over-trusting drivers and the resulting system misuse from a legal\nviewpoint. It looks at what the manufacturers of self-driving cars should legally do to ensure that drivers understand how to\nuse the vehicles appropriately.\n      One solution suggested in the study involves requiring buyers to sign end-user license agreements (EULAs), similar to\nthe terms and conditions that require agreement when using new software products. But this is far from ideal. The agreement\nmay not provide enough information to the driver, leading to confusion about the nature of the requests for agreement and\ntheir implications. Further, most end users don��t read EULAs. A 2017 study shows 91 percent of people agree to them without\nreading. Among young people, 97 percent agree without reviewing the terms.\n      The issue is that, unlike using a smartphone app, operating a car has serious safety risks, whether the driver is human or\nsoftware. And human drivers need to consent to take responsibility for the outcomes of the software and hardware.\n      ��Warning fatigue�� and distracted driving are also causes for concern. For example, a driver, annoyed after receiving\ncontinuous warnings, could decide to just ignore the message. Or, if the message is presented while the vehicle is in motion,\nit could represent a distraction. Given these limitations and concerns, even if this mode of obtaining consent is to move\nforward, it likely won��t fully protect automakers from their legal liability should the system malfunction (��������) or an\naccident occur.\nDriver training for self-driving vehicles can help ensure that drivers fully understand system capabilities and limitations. This\nneeds to occur beyond the vehicle purchase. Recent evidence shows even relying on the information provided by the seller is\nnot going to answer many questions. All of this considered, the road forward for self-driving cars is not going to be a smooth\nride after all.","questions":[{"n":46,"stem":"What do we learn from research in human-vehicle interaction?","options":{"A":"Automatic driving systems are by no means immune to errors.","B":"Driverless vehicles are likely to be misused by some people.","C":"Self-driving car manufacturers are not aware of the legal matters involved.","D":"There is a long way to go before humans can interact with driverless vehicles."},"answer":"A"},{"n":47,"stem":"What is the problem with requiring buyers to sign end-user license agreements?","options":{"A":"End users, young and old alike, find the terms complex to interpret.","B":"Most end users sign them without bothering to read the terms.","C":"Many people are often confused by the wording of the terms.","D":"Most end users do not understand the terms after reading them through."},"answer":"B"},{"n":48,"stem":"What would drivers do when they suffer from ��warning fatigue��?","options":{"A":"Waste no time keeping the car moving.","C":"Take no action despite repeated warnings.","B":"Rest a while to avoid fatigue driving.","D":"Take note of the message though fatigued."},"answer":"C"},{"n":49,"stem":"What does the author think of continuing to ask buyers to sign end-user license agreements?","options":{"A":"It will probably not guarantee the safety of drivers in case of accidents.","B":"It likely won��t ensure that the automatic driving system functions properly.","C":"It likely won��t fully protect automakers against accusations of deliberate cheating.","D":"It will probably not provide manufacturers adequate protection from legal responsibilities."},"answer":"D"},{"n":50,"stem":"What should be done to help drivers fully understand system capabilities and limitations?","options":{"A":"Training them to be experts in vehicle automation.","B":"Familiarizing them with the systems through training,","C":"Broadening their knowledge of accident-prevention mechanisms.","D":"Facilitating their access to the information provided by the seller."},"answer":"B"}]},{"title":"Passage Two","passage":"Do you ever blend up a protein drink for breakfast or grab a protein bar following an afternoon workout? If so, you are\nlikely among the millions of people in search of more protein-rich diets.\n      Protein-enriched products are found everywhere. But contrary to all the publicity that everyone needs more protein, most\nAmericans get twice as much as they need.\n      Many of us living in the most developed countries are buying into a myth of protein deficiency created by food companies\nand self-identified health experts. Global retail sales of protein supplement products reached an astonishing US$18.9 billion\nin 2020.\n      But are we really in need of more protein? Physicians in the U.S. have never actually examined a patient with protein\ndeficiency because simply by eating an adequate number of daily calories we are also most likely getting enough protein.\n      In fact, Americans currently consume almost twice the National Academy of Medicine��s recommended daily intake of\nprotein although the most desirable protein intake may vary depending on age and activity level.\n      For example, if you��re a dedicated athlete you might need to consume higher quantities of protein. Generally, though, a\n140-pound person should not exceed 120 grams of protein per day, particularly because a high protein diet can strain kidney\nand liver function and increase risks of developing heart disease and cancer.\n      While fats and sugar have taken the beating in turns since over a century ago, protein has managed to remain our red-hot\nfavorite.\n      In the 1970s through the 1990s, protein products remained visible but moved back somewhat with the dietary spotlight\nfirmly fixed on low-calorie, low-fat, sugar-free snack foods and beverages following the publication of studies linking sugar\nand saturated (���͵�) fat consumption to heart disease.\n      Later research in 2003, however, suggested high-protein diets could aid in weight loss, and protein quickly regained its\nformer nutrient-superstar status.\n      Now most people living in high-income nations are consuming enough protein. When we replace meals with a protein\nbar or drink, we also risk missing out on the rich sources of antioxidants (��������), vitamins and many other benefits of\nreal food.","questions":[{"n":51,"stem":"What do we learn about publicity over protein in America?","options":{"A":"It has helped to create the myth of protein deficiency.","B":"It has helped Americans in search of protein-rich diets.","C":"It has raised a lot of health concerns among the public.","D":"It has been funded by food companies and health experts."},"answer":"A"},{"n":52,"stem":"Why have physicians in the U.S. never actually examined a patient with protein deficiency?","options":{"A":"Americans can purchase many kinds of protein-rich foods everywhere.","B":"Americans can absorb the number of calories recommended by food experts.","C":"Americans can get sufficient protein just by eating adequate foods daily.","D":"Americans can rely on food supplements to prevent protein deficiency."},"answer":"C"},{"n":53,"stem":"What should people take into consideration in deciding on the most preferable protein intake?","options":{"A":"How healthy they are and what food they eat.","B":"How old they are and what activities they do.","C":"How much protein they consume and what their body weight is.","D":"How serious their protein deficiency is and what remedies they use."},"answer":"B"},{"n":54,"stem":"What foods have been largely out of favor for more than a century?","options":{"A":"Sugar-free snacks.","C":"Both red and white meats.","B":"Protein-rich foods.","D":"Sugary and fatty foods."},"answer":"D"},{"n":55,"stem":"What does the author imply people in developed countries should do to keep healthy?","options":{"A":"Enjoy natural food.","C":"Consume enough protein daily.","B":"Eat vegetarian diets.","D":"Replace meals with protein bars."},"answer":"A"}]}],"translation":{"prompt":"Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your\nanswer on Answer Sheet 2.\n\n�ػ�Ī�߿�(Mogao Grottoes)����չʾ������ 2014 �꿪������,��Ī�߿߱������ù��̵���Ҫ��ɲ��֡�չʾ���Ĳ�\n�����ּ����Ͷ�ý��չʾ�ֶ�,ʹ�οͽ��붴�߲ι�֮ǰ�����˽�Ī�߿ߵ���ʷ�Ļ�,����Ī�߿ߵ��������䡣�⽫\n���ٿ��Ŷ��ߵ�����,�����ο��ڶ����ڵĶ���ʱ��,����ι۶�Ī�߿���ɵ�Ӱ��,��ʹ��һ�����Ļ��Ų��õ�����\n�������������á�","guide":[]}});})();
